namespace qqworld_collector\module\collecting\method; require_once dirname(__DIR__) . '/security-boundaries.php'; use qqworld_collector\lib; class digital extends lib { var $guid = 'digital'; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse') ); } public function parse($value) { $random = explode('<!--s-->', $value); if (count($random) > 1) { $random = array_filter($random, array($this, 'is_not_empty')); foreach ($random as &$str) { $str = trim($str); } $value = $random[array_rand($random)]; } $value = apply_filters( 'qqworld-collector-collection-project-variable-filter', $value, 0 ); $parsed = \qqworld_collector\security\arithmetic($value); $value = $parsed === false ? '' : $parsed; $results = array($value); return $results; } } ?>